def f(n: int, A: List[int], m: int, B: List[int]) -> int:
    i = 0
    j = 0
    result = 0

    while i < n and j < m:
        if A[i] < B[j]:
            result += A[i]
            i += 1
        else:
            j += 1

    while i < n:
        result += A[i]
        i += 1

    while j < m:
        j += 1

    return result
```

